<span class="line"><span style="color:#C678DD;">            var</span><span style="color:#E06C75;"> defaultPolicy</span><span style="color:#56B6C2;"> =</span><span style="color:#ABB2BF;"> await </span><span style="color:#E5C07B;">policyProvider</span><span style="color:#ABB2BF;">.</span><span style="color:#61AFEF;">GetDefaultPolicyAsync</span><span style="color:#ABB2BF;">();</span></span>
