<span class="line"><span style="color:#C678DD;">    public</span><span style="color:#61AFEF;"> RoleRequirement</span><span style="color:#ABB2BF;">(</span><span style="color:#C678DD;">string</span><span style="color:#E5C07B;"> role</span><span style="color:#ABB2BF;">) =&gt; </span><span style="color:#E06C75;">Role</span><span style="color:#56B6C2;"> =</span><span style="color:#E06C75;"> role</span><span style="color:#ABB2BF;">;</span></span>
